// Implementação Web: toca um bipe curto sintetizado (sem depender de
// nenhum asset externo) via o construtor Audio() do navegador, usado
// quando uma nova notificação chega em tempo real com a aba aberta.
import 'dart:js_interop';

@JS('Audio')
extension type _JSAudio._(JSObject _) implements JSObject {
  external _JSAudio(JSString src);
  external void play();
}

// Bipe de dois tons (880Hz -> 1180Hz, ~260ms) gerado localmente — ver
// docs/ (script gen_beep.js usado para gerar este WAV) se precisar trocar.
const String _beepDataUri = 'data:audio/wav;base64,';

void playNotificationSound() {
  try {
    _JSAudio(_beepDataUri.toJS).play();
  } catch (_) {
    // Alguns navegadores bloqueiam autoplay de áudio sem interação prévia
    // do usuário — falha silenciosa, o toast visual já cobre o aviso.
  }
}
